DCALT(["dc.106:1"],{dc_oliver:"nolink"}); // Warren A. Cowdery
DCALT(["dc.113:7"],{dc_elias:"nolink"}); // Elias Higbee
DCALT(["dc.124:136"],{mos_noah:"nolink"}); // Noah Packard
